        @Override
        public void onEvent(Event event) throws FalconException {
            JobScheduledEvent scheduledEvent = ((JobScheduledEvent) event);
            if (scheduledEvent.getStatus() != JobScheduledEvent.STATUS.FAILED) {
                failed = true;
            }
        }

        @Override
        public PRIORITY getPriority() {
            return PRIORITY.MEDIUM;
        }
    };
    SchedulerService.JobScheduleRequestBuilder request = (SchedulerService.JobScheduleRequestBuilder) scheduler.createRequestBuilder(failureHandler, instance1.getId());
